public class RtpksManifest {
    public static final String FORMAT = "pokemon_resort.rtpks";
    public static final int VERSION = 2;
    public String tileIndex = "index/tile_index.json";
    public String tileTabs = "index/tile_tabs.json";
    public EditorPayload editorPayload = new EditorPayload();
}

const JsonValue manifest = extractJson(zip, "manifest.json");
if (intOr(manifest.get("version"), 0) != 2) {
    throw std::runtime_error("Unsupported RTPKS package. Re-export as RTPKS v2");
}
const JsonValue runtime = extractJson(zip, "runtime/manifest.json");
